#!/usr/bin/env bash
#
# Description: Makes <dir>/config.kdl axiom's for the "managed" niri mode
#              (NiriConfigWriter), says what that would do, or gives it
#              back when axiom leaves that mode. claim_sway.sh's
#              counterpart, with the same verbs and results.
# Usage:       claim_niri.sh check <dir> <header> [<fallback>]
#              claim_niri.sh claim <dir> <header> [<fallback>]
#              claim_niri.sh release <dir> <header> <fallback>
#              header: the first line prefix of a file axiom wrote
#              ("// Generated by axiom"); fallback: the config release
#              writes when nothing was set aside. Prints one word:
#                ours     the file is already axiom's
#                blocked:link       <dir> or its config is a symlink
#                blocked:git:<repo> <dir> is in the git repository <repo>
#                         either way never taken over
#                adopt    (check) an existing config would be moved
#                stock    (check) config.kdl is niri's default config
#                         ($AXIOM_NIRI_EXAMPLE, else
#                         /usr/share/doc/niri/default-config.kdl, which niri
#                         writes when there's none), give or take comments,
#                         blank lines and a line starting axiom: it would
#                         only be backed up, since its binds would fight
#                         axiom's
#                released (check) config.kdl is <fallback>, as release
#                         wrote it: replaced, with no backup
#                new      (check) there's no config yet
#                adopted:<name>  (claim) done: user/ exists, and the
#                         existing config is copied to user/<name>
#                         (00-previous.kdl, or 00-previous-<date>.kdl when
#                         that's taken), with a dated copy beside the
#                         original. In the copy, the nodes that start axiom
#                         or include its module are commented out (/-: the
#                         managed config does both), and relative includes
#                         made absolute (it's in user/ now)
#                created  (claim) done: user/ exists; there was no config
#                replaced (claim) done: user/ exists, and the default
#                         config is only kept as the dated copy
#              claim leaves config.kdl where it is, for the managed one to
#              replace (an atomic write). A claim of the same file again
#              (that write never came) reuses its copies. Writes nothing on
#              check, ours or blocked.
#              release prints one word too:
#                notours  config.kdl isn't axiom's (or is missing): nothing
#                         written
#                blocked:link, blocked:git:<repo>  as above, nothing written
#                restored:<from>:<n>  done: config.kdl is what claim set
#                         aside again (user/<name>, the newest adopted, its
#                         axiom nodes enabled again, or else the newest
#                         config.kdl.axiom-backup-*); <n> files in user/ it
#                         doesn't include (0 when it includes them)
#                written  done: nothing was set aside, so config.kdl is
#                         <fallback> (the user's, including user/)

set -uo pipefail

action=${1:-}
dir=${2:-}
header=${3:-}
example=${AXIOM_NIRI_EXAMPLE:-/usr/share/doc/niri/default-config.kdl}
fallback=${4:-}
if [[ "$action" != "check" && "$action" != "claim" && "$action" != "release" ]] || [[ -z "$dir" || -z "$header" ]] ||
  [[ "$action" == "release" && -z "$fallback" ]]; then
  echo "Usage: $0 check|claim <dir> <header> [<fallback>] | release <dir> <header> <fallback>" >&2
  exit 2
fi
dir=${dir%/}
file=$dir/config.kdl

is_ours() {
  [[ -f "$file" ]] && [[ "$(head -n 1 "$file")" == "$header"* ]]
}
if [[ "$action" == "release" ]]; then
  if ! is_ours; then
    echo notours
    exit 0
  fi
elif is_ours; then
  echo ours
  exit 0
fi
if [[ -L "$dir" || -L "$file" ]]; then
  echo blocked:link
  exit 0
fi
if repo=$(git -C "$dir" rev-parse --show-toplevel 2>/dev/null); then
  echo "blocked:git:$repo"
  exit 0
fi

# The nodes that start axiom (a spawn-at-startup or spawn-sh-at-startup of
# any `qs … -c axiom` / `-p …axiom` or `axiom run`, flags after it at most, so not an IPC
# call) or include its module. Not a bind calling axiom: the bind merge
# reads those. `sep` is what's between two words: a space in a
# spawn-sh-at-startup's string, `" "` between spawn-at-startup's arguments
sep='("[[:space:]]+"|[[:space:]]+)'
axiom_line="^[[:space:]]*(spawn(-sh)?-at-startup[[:space:]]+\"([^\"]*[[:space:]])?(qs|quickshell)${sep}(-c${sep}['\"]?axiom['\"]?|-p${sep}'?[^[:space:]\"']*axiom'?)(${sep}-[^[:space:]\"]+)*\"[[:space:]]*(;.*)?\$|spawn(-sh)?-at-startup[[:space:]]+\"([^\"]*[[:space:]])?'?([^[:space:]\"']*/)?axiom'?${sep}run(${sep}-[^[:space:]\"]+)*\"[[:space:]]*(;.*)?\$|include[[:space:]].*axiom/niri(-detached)?\\.kdl)"

# The default config, give or take comments, blank lines and whitespace,
# and a line starting axiom
stock_lines() {
  grep -vE "^[[:space:]]*(//|$)|$axiom_line" "$1"
}
is_stock() {
  [[ -f "$example" ]] && diff -qbB <(stock_lines "$file") <(stock_lines "$example") >/dev/null 2>&1
}
# The file release writes, give or take whitespace, blank lines and the
# node including the module (it has it when written for that mode)
released_lines() {
  grep -vE 'include .*axiom/niri\.kdl'
}
is_released() {
  [[ -n "$fallback" ]] && diff -qbB <(released_lines <"$file") <(printf '%s\n' "$fallback" | released_lines) >/dev/null 2>&1
}

marker='/* (axiom starts and loads itself now) */ /-'
# The marker as a sed -E pattern
marker_re=$(printf '%s' "$marker" | sed 's/[()*/]/\\&/g')

# In the adopted copy: comments out the nodes starting axiom or including
# its module, and makes relative includes absolute (from <dir>)
adopt_lines() {
  local target=$1 edited
  edited=$(mktemp) || return 1
  sed -E \
    -e '/^[[:space:]]*\/\//b' \
    -e "\%$axiom_line%s%^%$marker%" \
    -e "s|^([[:space:]]*include[[:space:]][^\"]*\")([^/\"~\$][^\"]*\")|\\1$dir/\\2|" \
    "$target" >"$edited" && cat "$edited" >"$target"
  rm -f "$edited"
}

# Undoes the commenting out in a copy of <file> at <target>
enable_axiom_lines() {
  sed -E "s/^$marker_re//" "$1" >"$2"
}

newest_previous() {
  local dated
  dated=$(find -H "$dir/user" -maxdepth 1 -name '00-previous-*.kdl' -printf '%f\n' 2>/dev/null | sort | tail -n 1)
  if [[ -n "$dated" ]]; then
    echo "$dated"
  elif [[ -f "$dir/user/00-previous.kdl" ]]; then
    echo 00-previous.kdl
  fi
}
newest_backup() {
  find "$dir" -maxdepth 1 -name 'config.kdl.axiom-backup-*' -printf '%f\n' 2>/dev/null | sort | tail -n 1
}

if [[ "$action" == "release" ]]; then
  previous=$(newest_previous)
  backup=$(newest_backup)
  staged=$(mktemp "$dir/.config.kdl.XXXXXX") || exit 1
  trap 'rm -f "$staged"' EXIT
  if [[ -n "$previous" ]]; then
    enable_axiom_lines "$dir/user/$previous" "$staged" && chmod --reference="$dir/user/$previous" "$staged" &&
      mv "$staged" "$file" && rm -f "$dir/user/$previous" || exit 1
    from=user/$previous
  elif [[ -n "$backup" ]]; then
    mv "$dir/$backup" "$file" || exit 1
    from=$backup
  else
    printf '%s\n' "$fallback" >"$staged" && chmod 644 "$staged" && mv "$staged" "$file" || exit 1
    echo written
    exit 0
  fi
  # The user/ files the restored config doesn't include (niri takes no
  # globs: each is named)
  left=0
  while IFS= read -r name; do
    grep -qE "^[[:space:]]*include[[:space:]].*/user/$name\"" "$file" || left=$((left + 1))
  done < <(find -H "$dir/user" -maxdepth 1 -type f -name '*.kdl' -printf '%f\n' 2>/dev/null)
  echo "restored:$from:$left"
  exit 0
fi

if [[ "$action" == "check" ]]; then
  if [[ ! -f "$file" ]]; then
    echo new
  elif is_stock; then
    echo stock
  elif is_released; then
    echo released
  else
    echo adopt
  fi
  exit 0
fi

mkdir -p "$dir/user" || exit 1
if [[ -f "$file" ]]; then
  backup="$file.axiom-backup-$(date +%Y%m%d-%H%M%S)"
  if is_released; then
    echo replaced
    exit 0
  fi
  # Already copied by a claim whose managed write never came
  last=$(newest_backup)
  if [[ -n "$last" ]] && cmp -s "$file" "$dir/$last"; then
    previous=$(newest_previous)
    if is_stock; then
      echo replaced
      exit 0
    elif [[ -n "$previous" ]]; then
      echo "adopted:$previous"
      exit 0
    fi
  fi
  if is_stock; then
    cp -p "$file" "$backup" || exit 1
    echo replaced
    exit 0
  fi
  name=00-previous.kdl
  [[ -e "$dir/user/$name" ]] && name=00-previous-$(date +%Y%m%d-%H%M%S).kdl
  cp -p "$file" "$backup" && cp -p "$file" "$dir/user/$name" || exit 1
  adopt_lines "$dir/user/$name"
  echo "adopted:$name"
  exit 0
fi
echo created
